fn required(name: &str) -> PathBuf { fs::canonicalize(std::env::var_os(name).unwrap_or_else(|| panic!("{name} is required"))).unwrap() }
fn identity(name: &str, _executable: &Path, _digest: signal::ContractDigest) -> translator::PeerBinding {
    translator::PeerBinding { peer_id: translator::PeerId(name.into()), peer_identity: translator::PeerIdentity { user_id: translator::UserId(i64::from(nix::unistd::getuid().as_raw())), process_id: translator::ProcessId(i64::from(std::process::id())) } }
}
fn write_bootstrap<T: Signalizable>(child: &mut Child, value: &T) {
    let archived=value.signalize().unwrap(); child.stdin.as_mut().unwrap().write_frame(&FrameBody::from(archived.bytes().to_vec()), signal::FrameCapacity::default()).unwrap(); drop(child.stdin.take());
}
fn explicit_place(directory: &Path) -> translator::Place {
    translator::Place {
        place_name: translator::PlaceName("proof".into()),
        runtime: translator::Runtime(directory.to_string_lossy().into_owned()),
        state: translator::State(directory.to_string_lossy().into_owned()),
    }
}
fn write_nexus_bootstrap(child: &mut Child, value: &meta::NexusBootstrap) {
    use meta::Enveloped;
    child.stdin.as_mut().unwrap().write_frame(&FrameBody::from(meta::NexusBootstrap::envelope()), signal::FrameCapacity::default()).unwrap();
    write_bootstrap(child, value);
}
fn wait(path: &Path) { for _ in 0..500 { if path.exists(){return} thread::sleep(Duration::from_millis(10)); } panic!("socket did not appear: {}",path.display()) }
fn eventually(what: &str, mut condition: impl FnMut() -> bool) { for _ in 0..1000 { if condition() { return } thread::sleep(Duration::from_millis(10)); } panic!("did not happen within 10s: {what}") }
fn command(exe:&Path,args:&[String])->Output { let o=Command::new(exe).args(args).output().unwrap(); assert!(o.status.success(),"{} failed {:?}: {}",exe.display(),o.status.code().or_else(||o.status.signal()),String::from_utf8_lossy(&o.stderr)); o }
fn configure(meta_cli:&Path,socket:&Path,revision:i64,set:meta::Set) -> String { let query=meta::Query::Configure(meta::ConfigureRequest{configuration_revision_option:Some(meta::ConfigurationRevision(revision)),set}); let text=encode_meta_query(&query); let out=command(meta_cli,&[socket.to_string_lossy().into_owned(),text]); let answer=String::from_utf8(out.stdout).unwrap(); assert!(answer.starts_with("Configured."),"{answer}"); answer }
fn public(cli:&Path,socket:&Path,query:wire::Query)->String { let out=command(cli,&[socket.to_string_lossy().into_owned(),encode_public_query(&query)]); String::from_utf8(out.stdout).unwrap() }
fn git(dir:&Path,args:&[&str]) { let o=Command::new("git").current_dir(dir).args(args).output().unwrap(); assert!(o.status.success(),"git {:?}: {}",args,String::from_utf8_lossy(&o.stderr)); }

